/* Zephyr ADC example – reads a single channel and prints the result in millivolts */

#include <zephyr/kernel.h>
#include <zephyr/drivers/adc.h>

/* Get the ADC device and channel defined in the devicetree under the
 * node "zephyr_user".  The node must contain the needed properties
 * for the ADC channel.
 */
#define ADC_NODE DT_PATH(zephyr_user)
static const struct adc_dt_spec adc_spec = ADC_DT_SPEC_GET(ADC_NODE);

/* The ADC sequence that will be used for each read.  The buffer
 * contains a single sample.
 */
static int16_t buf;
static const struct adc_sequence seq = {
    .channels = BIT(adc_spec.channel_cfg.channel_id),
    .buffer   = &buf,
    .buffer_size = sizeof(buf),
    .no_of_values = 1,
    .resolution = adc_spec.channel_cfg.resolution,
    .oversampling = adc_spec.channel_cfg.oversampling,
};

int main(void)
{
    int rc;

    /* Ensure the ADC device is ready before attempting any work. */
    if (!adc_spec.ready) {
        printk("ADC device not ready\n");
        return 0;
    }

    /* Configure the channel. */
    rc = adc_channel_setup_dt(&adc_spec, &adc_spec.channel_cfg);
    if (rc < 0) {
        printk("adc_channel_setup_dt failed: %d\n", rc);
        return rc;
    }

    while (1) {
        /* Perform the read. */
        rc = adc_read_dt(&adc_spec, &seq);
        if (rc < 0) {
            printk("adc_read_dt failed: %d\n", rc);
            continue;
        }

        /* Convert raw value to millivolts. */
        int32_t mv = adc_raw_to_millivolts_dt(&adc_spec, &seq, buf);
        printk("%d mV\n", mv);

        /* Wait a second before the next sample. */
        k_sleep(K_MSEC(1000));
    }

    return 0;
}
